const req = state.pending;
if (req?.result && req.id === state.requestId) {
  state.pending = null;
  if (req.result.image) { revoke(state.image); state.image = req.result.image; captured = true; }
  else warnOnce(`snapshot: ${req.result.message}`);           // Image keeps the previous picture
