  if (snap === undefined) logOnce("snapshot: no renderer in simulation");
  else {
    const r = { id: ++state.requestId, result: null };        // a newer capture supersedes an older one
    state.pending = r;
    snap(ctx.input("layer"), { scale: ctx.services.device().screenScale }).then(
