  const px = read(ref, 256);     // { width, height, data: RGBA bytes, frameId, contentSize: [cw, ch], contentRect: [x, y, w, h] } or undefined
  if (px === undefined) state.error = "The layer's pixels can't be read yet, or the media blocks reading (CORS).";
  else if (px.frameId !== state.lastFrame) {
